import { useState } from 'react';
import type { ChangeEvent } from 'react';
import { JxStepper, JxInputField, JxButton } from '@jinx-ui/react';

interface RegistrationData {
  name: string;
  email: string;
  phone: string;
  street: string;
  city: string;
  zip: string;
}

interface RegistrationWizardProps {
  onSubmit: (data: RegistrationData) => void;
}

const STEPS = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

const emptyData: RegistrationData = {
  name: '',
  email: '',
  phone: '',
  street: '',
  city: '',
  zip: '',
};

export default function RegistrationWizard({ onSubmit }: RegistrationWizardProps) {
  const [step, setStep] = useState(0);
  const [data, setData] = useState<RegistrationData>(emptyData);
  const [touched, setTouched] = useState(false);

  const update = (field: keyof RegistrationData) => (event: ChangeEvent<HTMLInputElement>) => {
    setData((prev) => ({ ...prev, [field]: event.target.value }));
  };

  const errorIfEmpty = (value: string) => (touched && value.trim() === '' ? 'Заполните поле' : undefined);

  const isStepValid = () => {
    if (step === 0) return data.name.trim() !== '' && data.email.includes('@') && data.phone.trim() !== '';
    if (step === 1) return data.street.trim() !== '' && data.city.trim() !== '' && data.zip.trim() !== '';
    return true;
  };

  const goNext = () => {
    if (!isStepValid()) {
      setTouched(true);
      return;
    }
    setTouched(false);
    setStep((current) => Math.min(current + 1, STEPS.length - 1));
  };

  const goBack = () => {
    setTouched(false);
    setStep((current) => Math.max(current - 1, 0));
  };

  const handleSubmit = () => {
    if (!isStepValid()) {
      setTouched(true);
      return;
    }
    onSubmit(data);
  };

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '24px',
        maxWidth: '480px',
        padding: '24px',
        borderRadius: 'var(--jx-radius-lg)',
        background: 'var(--jx-color-surface)',
        boxShadow: 'var(--jx-shadow-md)',
        fontFamily: 'var(--jx-font-body)',
      }}
    >
      <JxStepper steps={STEPS} current={step} />

      {step === 0 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
          <JxInputField
            label="Имя"
            required
            value={data.name}
            onChange={update('name')}
            errorText={errorIfEmpty(data.name)}
          />
          <JxInputField
            label="Электронная почта"
            type="email"
            required
            value={data.email}
            onChange={update('email')}
            errorText={
              touched && !data.email.includes('@') ? 'Укажите адрес с символом @' : undefined
            }
          />
          <JxInputField
            label="Телефон"
            prefix="+7"
            required
            value={data.phone}
            onChange={update('phone')}
            errorText={errorIfEmpty(data.phone)}
          />
        </div>
      )}

      {step === 1 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
          <JxInputField
            label="Улица и дом"
            required
            value={data.street}
            onChange={update('street')}
            errorText={errorIfEmpty(data.street)}
          />
          <JxInputField
            label="Город"
            required
            value={data.city}
            onChange={update('city')}
            errorText={errorIfEmpty(data.city)}
          />
          <JxInputField
            label="Индекс"
            required
            value={data.zip}
            onChange={update('zip')}
            errorText={errorIfEmpty(data.zip)}
          />
        </div>
      )}

      {step === 2 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
          <p style={{ color: 'var(--jx-color-text)', fontWeight: 600 }}>Проверьте данные</p>
          <p style={{ color: 'var(--jx-color-text)' }}>Имя: {data.name}</p>
          <p style={{ color: 'var(--jx-color-text)' }}>Email: {data.email}</p>
          <p style={{ color: 'var(--jx-color-text)' }}>Телефон: {data.phone}</p>
          <p style={{ color: 'var(--jx-color-text)' }}>Адрес: {data.street}, {data.city}, {data.zip}</p>
        </div>
      )}

      <div style={{ display: 'flex', justifyContent: 'space-between', gap: '12px' }}>
        <JxButton variant="ghost" type="button" disabled={step === 0} onClick={goBack}>
          Назад
        </JxButton>
        {step < STEPS.length - 1 ? (
          <JxButton variant="primary" type="button" onClick={goNext}>
            Дальше
          </JxButton>
        ) : (
          <JxButton variant="primary" type="button" onClick={handleSubmit}>
            Отправить
          </JxButton>
        )}
      </div>
    </div>
  );
}

